$(() => {
  $(document).on("input keydown keyup mousedown mouseup select contextmenu drop focusout", "input[data-valformat=withspacesforthreenumbers]", function(e){
    const input = event.target;
    const inputValue = $(input).val();
    const numericValue = inputValue.replace(/[^\d]/g, '');
    const formattedValue = numericValue.replace(/(\d{3})(?=\d)/g, '$1 ');
    $(input).val(formattedValue);
  });

  var maxLength = 350;
  $('#message-text').on('input', function(){
    var textLength = $(this).val().length;
    if(textLength > maxLength){
      $(this).val($(this).val().substring(0, maxLength));
      textLength = maxLength;
    }
    $('#charCount').text(textLength);
  });

  $('#message-text').on('keypress keyup', function(event){
    var textLength = $(this).val().length;
    if(textLength >= maxLength && event.which !== 8 && event.which !== 46){
      event.preventDefault();
      $('#charCount').addClass('limit-max');
    }else{
      $('#charCount').removeClass('limit-max');
    }
  });
});